WITH r AS (
  SELECT src, dst FROM relations_at('hyperledger', TIMESTAMP '2019-10-04 22:01') WHERE rel = 'relates_to'
),
seeds AS (
  SELECT DISTINCT dst AS s FROM r WHERE src = 'issue:INDY-1703'
  UNION SELECT DISTINCT src FROM r WHERE dst = 'issue:INDY-1703'
),
nbrs AS (
  SELECT r.dst AS n FROM r JOIN seeds ON r.src = seeds.s
  UNION
  SELECT r.src FROM r JOIN seeds ON r.dst = seeds.s
)
SELECT DISTINCT n FROM nbrs WHERE n <> 'issue:INDY-1703' AND n NOT IN (SELECT s FROM seeds) ORDER BY n;

