WITH d AS (
  SELECT src AS a, dst AS b FROM relations_at('spring', TIMESTAMP '2008-11-04 06:33') WHERE rel = 'duplicates'
),
n1 AS (
  SELECT DISTINCT CASE WHEN a = 'issue:SEC-407' THEN b ELSE a END AS x
  FROM d WHERE a = 'issue:SEC-407' OR b = 'issue:SEC-407'
),
n2 AS (
  SELECT DISTINCT CASE WHEN d.a = n1.x THEN d.b ELSE d.a END AS y
  FROM d JOIN n1 ON d.a = n1.x OR d.b = n1.x
)
SELECT y FROM n2 WHERE y <> 'issue:SEC-407' AND y NOT IN (SELECT x FROM n1) ORDER BY y;

