WITH s AS (
  SELECT 'Closed' AS st, TIMESTAMP '2013-06-04 23:31:07.152' AS a, TIMESTAMP '2013-06-06 07:37:53.952' AS b
  UNION ALL SELECT 'Closed', TIMESTAMP '2013-06-06 07:39:55.868', TIMESTAMP '2015-11-15 12:20'
