SELECT SUM(keel_days(a, b)) AS total_days, FLOOR(SUM(keel_days(a, b))) AS whole_days FROM s;

WITH r AS (SELECT src, rel, dst FROM relations_at('sakai-grbk', TIMESTAMP '2013-08-30 19:34') WHERE rel IN ('depends_on','duplicates')),
d AS (
  SELECT CASE WHEN src='issue:GRBK-752' THEN dst ELSE src END AS n FROM r WHERE rel='depends_on' AND (src='issue:GRBK-752' OR dst='issue:GRBK-752')
),
dup AS (
  SELECT CASE WHEN src IN (SELECT n FROM d) THEN dst ELSE src END AS m FROM r WHERE rel='duplicates' AND (src IN (SELECT n FROM d) OR dst IN (SELECT n FROM d))
)
SELECT DISTINCT m FROM dup WHERE m <> 'issue:GRBK-752' AND m NOT IN (SELECT n FROM d) ORDER BY m;

