WITH r AS (
  SELECT src, dst FROM relations_at('ecosystem-ac', TIMESTAMP '2019-09-17 05:23') WHERE rel = 'relates_to'
),
undirected AS (
  SELECT src AS a, dst AS b FROM r
  UNION
  SELECT dst AS a, src AS b FROM r
),
seed AS (
  SELECT b AS s FROM undirected WHERE a = 'issue:AC-2434'
),
hop2 AS (
  SELECT DISTINCT u.b AS n FROM undirected u JOIN seed s ON u.a = s.s
)
SELECT n FROM hop2 WHERE n <> 'issue:AC-2434' AND n NOT IN (SELECT s FROM seed) ORDER BY n;

