WITH r AS (
  SELECT src, dst FROM relations_at('apache-tajo', TIMESTAMP '2016-08-12 00:25') WHERE rel = 'relates_to'
),
n1 AS (
  SELECT DISTINCT CASE WHEN src = 'issue:TAJO-356' THEN dst ELSE src END AS nb
  FROM r WHERE src = 'issue:TAJO-356' OR dst = 'issue:TAJO-356'
),
n2 AS (
  SELECT DISTINCT CASE WHEN r.src IN (SELECT nb FROM n1) THEN r.dst ELSE r.src END AS nb2
  FROM r WHERE r.src IN (SELECT nb FROM n1) OR r.dst IN (SELECT nb FROM n1)
