WITH r AS (
  SELECT src, dst FROM relations_at('apache-tajo', TIMESTAMP '2016-08-12 00:25') WHERE rel = 'relates_to'
  UNION ALL
  SELECT dst AS src, src AS dst FROM relations_at('apache-tajo', TIMESTAMP '2016-08-12 00:25') WHERE rel = 'relates_to'
),
first_hop AS (
  SELECT DISTINCT dst AS n FROM r WHERE src = 'issue:TAJO-356' AND dst <> 'issue:TAJO-356'
),
second_hop AS (
  SELECT DISTINCT r.dst AS n FROM r JOIN first_hop f ON r.src = f.n
  WHERE r.dst <> 'issue:TAJO-356'
)
SELECT n FROM second_hop WHERE n NOT IN (SELECT n FROM first_hop) ORDER BY n;

