d AS (
  SELECT CASE WHEN src='issue:TAJO-694' THEN dst ELSE src END AS n FROM r
  WHERE rel='duplicates' AND (src='issue:TAJO-694' OR dst='issue:TAJO-694')
),
rel2 AS (
  SELECT CASE WHEN src IN (SELECT n FROM d) THEN dst ELSE src END AS m, src, dst FROM r
  WHERE rel='relates_to' AND (src IN (SELECT n FROM d) OR dst IN (SELECT n FROM d))
)
SELECT DISTINCT m FROM rel2 WHERE m <> 'issue:TAJO-694' AND m NOT IN (SELECT n FROM d) ORDER BY m;
